extra_css:
/* theme: navy-notebook (2026-10-27) */
:root,:root:not(x){--bg:#ffffff;--fg:#14215a;--muted:#4a5687;--line:#c9d1ee;--card:#fff;--soft:#f2f5ff;--accent:#1d3bb3;--accent2:#f5c400}
@media (prefers-color-scheme:dark){:root{--bg:#ffffff;--fg:#14215a;--muted:#4a5687;--line:#c9d1ee;--card:#fff;--soft:#f2f5ff;--accent:#1d3bb3;--accent2:#f5c400}}
body{font-family:"Zen Kaku Gothic New","Hiragino Sans",sans-serif;background-image:linear-gradient(#1d3bb30d 1px,transparent 1px),linear-gradient(90deg,#1d3bb30d 1px,transparent 1px);background-size:24px 24px}
header{background:#fff;border-bottom:2px solid #14215a}
.logo,.hero h1,article h1,.sec-h,article h2{font-weight:900}
.logo{color:#14215a}.logo span{background:linear-gradient(transparent 58%,#ffe34d 58%);color:#14215a}
.gnav a{background:#fff;border:1.5px solid #14215a;color:#14215a}
.gnav a:hover,.gnav a.on{background:#ffe34d;color:#14215a}
.hero-img{border:2px solid #14215a;border-radius:10px}
.sec-h{border-bottom:2px solid #14215a}
.card{border:2px solid #14215a;border-radius:10px}
.card:hover{border-color:#14215a;box-shadow:5px 5px 0 #ffe34d}
.tag{background:#14215a;color:#ffe34d}
article h2{background:none;border-left:0;border-bottom:2px solid #14215a;border-radius:0;padding:4px 2px}
article h2 span,article h2{background-image:linear-gradient(transparent 62%,#ffe34d 62%);background-repeat:no-repeat;background-size:100% 100%}
article h3{border-bottom:2px dotted #14215a}
.lead,.toc,.shop,aside .box,.author{border:2px solid #14215a}
.toc{border-top:6px solid #ffe34d}
.note{border-left:6px solid #f5c400;background:#fffbe0}
code,pre{font-family:"M PLUS 1 Code",ui-monospace,monospace}
code{background:#f2f5ff;border-color:#c9d1ee}
.picks{border:2px solid #14215a;box-shadow:5px 5px 0 #ffe34d}
.picks-h::before{content:"✎ "}
.next{border:2px dashed #14215a;background:#fffbe0}.next-h{color:#14215a}
.avatar{background:#ffe34d;color:#14215a;border:2px solid #14215a}
aside .box-h{border-bottom:2px solid #14215a}
.mini b{background:#14215a;color:#ffe34d}
th{background:#f2f5ff}
footer{background:#14215a;color:#c9d1ee;border-top:0}footer a{color:#ffe34d}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: prompt-card (2026-10-27) */
.hx-note .hx-h1 em{color:#14215a;background:linear-gradient(transparent 60%,#ffe34d 60%)}
.hx-card{background:#fff;border:2px solid #14215a;border-radius:12px;box-shadow:7px 7px 0 #ffe34d;overflow:hidden}
.hx-card-h{display:flex;align-items:center;gap:8px;font-weight:900;padding:10px 14px;border-bottom:2px solid #14215a;background:#f2f5ff}.hx-card-h small{margin-left:auto;font-size:12px;background:#14215a;color:#ffe34d;padding:1px 10px;border-radius:99px}
.hx-dot{width:12px;height:12px;border-radius:50%;background:#ffe34d;box-shadow:0 0 0 2px #14215a}
.hx-pre{margin:0;padding:14px 16px;min-height:220px;white-space:pre-wrap;font-family:"M PLUS 1 Code",ui-monospace,monospace;font-size:14px;line-height:1.8;color:#14215a;background:#fff;border:0}
.hx-card-f{display:flex;gap:10px;justify-content:flex-end;padding:10px 14px;border-top:2px dotted #c9d1ee}
.hx-copy{font:inherit;font-weight:700;font-size:13px;background:#ffe34d;color:#14215a;border:2px solid #14215a;border-radius:8px;padding:6px 14px;cursor:pointer}
.hx-go{font-weight:700;font-size:13px;color:#14215a;text-decoration:none;border-bottom:2px solid #ffe34d;padding:6px 2px}
.hx-note .hx-chips a{background:#fff;border:1.5px solid #14215a;color:#14215a;border-radius:99px}.hx-note .hx-chips a:hover{background:#ffe34d}
.hx-note .hx-vs{border:2px solid #14215a;border-radius:12px;padding:16px;background:#fff}
.hx-note .hx-side:not(.on) .hx-v{color:#8a93b8;text-decoration:line-through wavy #c9d1ee}.hx-note .hx-side.on .hx-v{background:linear-gradient(transparent 62%,#ffe34d 62%);display:inline}
.hx-note .hx-mid{font-size:26px;font-weight:900;color:#14215a}
.hx-note .hx-stats div{border:2px solid #14215a;border-radius:10px;padding:12px;background:#fff;text-align:center}
.hx-note .hx-stats b{font-size:clamp(30px,5vw,42px);color:#14215a}.hx-note .hx-stats b::after{content:"";display:block;width:34px;height:6px;background:#ffe34d;margin:4px auto 0}
.hx-note .hx-steps li{border:2px dashed #14215a;border-radius:10px;padding:12px;background:#fffbe0}.hx-note .hx-steps b{font-size:13px;color:#1d3bb3}

/* article-base: 2026-10-27 記事ページの共通部分 */
.ax-time{display:inline-block;font-size:12px;margin-left:8px}
.ax-prog{position:fixed;left:0;right:0;top:0;height:4px;z-index:50;pointer-events:none}.ax-prog i{display:block;height:100%;width:0}
.toc li.now>a{font-weight:700}
.ax-tick{cursor:pointer}li.ax-tick{position:relative;padding-left:30px}ul>li.ax-tick{list-style:none}ul>li.ax-tick::marker{content:""!important}
li.ax-tick::before,tr.ax-tick td:first-child::before{content:"";position:absolute;left:4px;top:.45em;width:16px;height:16px;border:2px solid currentColor;border-radius:4px;opacity:.55}
.ax-tick.done{opacity:.55;text-decoration:line-through}li.ax-tick.done::after,tr.ax-tick.done td:first-child::after{content:"✓";position:absolute;left:7px;top:.05em;font-weight:800}
tr.ax-tick td:first-child{position:relative;padding-left:32px}tr.ax-tick td:first-child::before{left:8px;top:.6em}tr.ax-tick.done td:first-child::after{left:11px;top:.2em}
.ax-copy{display:block;margin:10px 0 0 auto;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
@media print{.ax-prog,.ax-size,.ax-copy{display:none}}

/* article: prompt-notebook (2026-10-27) */
.ax-prog{background:#f2f5ff;border-bottom:1px solid #c9d1ee}.ax-prog i{background:#ffe34d;border-right:3px solid #14215a}
.ax-time{background:#ffe34d;color:#14215a;padding:0 8px;border-radius:4px;font-weight:700}
.lead strong{font-size:0}.lead strong::before{content:"✎ この記事でできること";font-size:14px;color:#14215a;background:linear-gradient(transparent 60%,#ffe34d 60%)}
.toc{counter-reset:pr}.toc strong{font-size:0}.toc strong::before{content:"もくじ";font-size:14px}
.toc ol{list-style:none;padding-left:0}.toc li{counter-increment:pr;padding:2px 0}.toc li::before{content:"□";margin-right:8px;color:#1d3bb3}.toc li.now::before{content:"■"}
article{counter-reset:ph}article h2{counter-increment:ph}article h2::before{content:"✎ " counter(ph) "  ";color:#1d3bb3}
article h2.ax-sum::before{content:"✔  "}
.note{position:relative;background:#fff;border:2px solid #14215a;border-left:2px solid #14215a;border-radius:10px;padding:30px 16px 12px;font-family:"M PLUS 1 Code",ui-monospace,monospace;font-size:14px;box-shadow:5px 5px 0 #ffe34d}
.note::before{content:"PROMPT";position:absolute;left:12px;top:6px;font-size:11px;letter-spacing:.2em;color:#4a5687;font-family:"Zen Kaku Gothic New",sans-serif;font-weight:700}
.ax-copy{background:#ffe34d;color:#14215a;border:2px solid #14215a;border-radius:8px;padding:5px 14px;font-family:"Zen Kaku Gothic New",sans-serif}
article ul li::marker{content:"✓ ";color:#1d3bb3}
